"""Compare generated bytes against the ai4rag 0.25.4 pre-migration baseline."""

import hashlib
import json
import warnings
import zipfile
from pathlib import Path

import pytest
from kfp_components.components.training.autorag.shared import assets_generator as generator

CASES = [
    (provider, template_id, compression)
    for provider, templates in (
        ("milvus", ("sequential_rag", "agentic_rag")),
        ("pgvector", ("sequential_rag", "agentic_rag")),
        ("neo4j", ("agentic_graph_rag",)),
    )
    for template_id in templates
    for compression in (True, False)
]
CASES += [("milvus", None, True), ("milvus", "invalid", True)]
NOTEBOOKS = (
    "maas_indexing",
    "maas_inference",
    "mass_creating_knowledge_graph",
    "mass_inference_knowledge_graph",
)


def pattern(provider, template_id, compression):
    """Return the same input for the original and moved implementations."""
    result = {
        "name": "migration-pattern",
        "settings": {
            "generation": {
                "model_id": "chat-model",
                "system_message_text": 'Use "evidence".\nKeep \\ paths and {braces}.',
                "user_message_text": "Question: {question}",
                "context_template_text": "Context: {context}",
                "temperature": 0.2,
                "max_completion_tokens": 256,
            },
            "embedding": {"model_id": "embed-model", "embedding_params": {"embedding_dimension": 768}},
            "store_binding": {"provider_type": provider, "collection_name": "production"},
            "retrieval": {
                "method": "simple",
                "number_of_chunks": 3,
                "search_mode": "graph" if provider == "neo4j" else "hybrid",
                "ranker_strategy": "rrf",
                "ranker_k": 42,
                "route_k": 4,
                "include_entity_neighbors": False,
                "entity_relationship_hops": 2,
            },
            "agentic": {"enable_context_compression": compression},
            "graph_extraction": {"mode": "constrained", "entity_types": ["Person"]},
        },
        "indexing": {"pipeline_spec": {"parameters": {"maas_secret_name": "maas", "db_secret_name": "database"}}},
    }
    if template_id is not None:
        result["template_id"] = template_id
    return result


def digest(content):
    """Normalize only the installed version and approved gateway documentation edits."""
    from ai4rag import __version__

    text = content.decode().replace(__version__, "<AI4RAG_VERSION>")
    text = text.replace("pipelines-components/scripts/setup-openshell-gateway.sh", "scripts/setup-openshell-gateway.sh")
    text = text.replace(
        " Use\n  [scripts/setup-openshell-gateway.sh](https://github.com/kubeflow/pipelines-components/blob/main/scripts/setup-openshell-gateway.sh).",
        "",
    )
    return hashlib.sha256(text.encode()).hexdigest()


def outputs(api, root, provider, template_id, compression):
    """Hash every notebook, unpacked ZIP entry, warning, and invalid-ID outcome."""
    data = pattern(provider, template_id, compression)
    output = {}
    root.mkdir(parents=True, exist_ok=True)
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        try:
            for notebook in NOTEBOOKS:
                path = root / f"{notebook}.ipynb"
                api.generate_notebook_from_template(
                    notebook,
                    data,
                    path,
                    test_data_key="benchmark/test.json",
                    input_data_keys=["documents/one/", "documents/two/"],
                )
                output[path.name] = digest(path.read_bytes())
            archive_path = api.generate_starter_kit(data, root)
            with zipfile.ZipFile(archive_path) as archive:
                output["zip"] = {name: digest(archive.read(name)) for name in sorted(archive.namelist())}
        except ValueError as error:
            output["error"] = str(error)
        output["warnings"] = [str(item.message) for item in caught]
    return output


@pytest.mark.parametrize(("provider", "template_id", "compression"), CASES)
def test_outputs_match_original(tmp_path, provider, template_id, compression):
    """Resource relocation preserves generated content and validation behavior."""
    baseline = json.loads((Path(__file__).parent / "test_data/relocation-baseline.json").read_text())
    key = f"{provider}:{template_id}:{compression}"
    assert outputs(generator, tmp_path, provider, template_id, compression) == baseline[key]


def test_empty_and_populated_leaderboards_match_original(tmp_path):
    """Empty optimization results and evaluated patterns retain the HTML contract."""
    baseline = json.loads((Path(__file__).parent / "test_data/relocation-baseline.json").read_text())
    assert digest(generator.build_leaderboard_html(tmp_path).encode()) == baseline["empty_leaderboard"]
    directory = tmp_path / "migration-pattern"
    directory.mkdir()
    (directory / "pattern.json").write_text(json.dumps(pattern("milvus", "agentic_rag", True)))
    assert digest(generator.build_leaderboard_html(tmp_path).encode()) == baseline["leaderboard"]


def test_version_is_from_ai4rag(tmp_path):
    """Artifacts continue depending on ai4rag rather than the host wheel version."""
    from ai4rag import __version__
    from kfp_components.components.training.autorag.shared.assets_generator.templates import create_placeholder_mapping

    data = pattern("milvus", "agentic_rag", True)
    assert create_placeholder_mapping(data)["AI4RAG_VERSION"] == __version__
    with zipfile.ZipFile(generator.generate_starter_kit(data, tmp_path)) as archive:
        assert f"ai4rag>={__version__}" in archive.read("starter_kit/pyproject.toml").decode()
        assert not any("setup-openshell-gateway" in name for name in archive.namelist())
